require dirname(__DIR__,2).'/custom/chinaplanetoperations/class/CustomerAccountView.class.php';
function m121s_assert($ok,$why){if(!$ok)throw new RuntimeException($why);}
class M121ScopeActor {
 public $id=7,$socid=0,$fk_soc=0,$admin=0,$statut=1;public $rights=array();
 public function hasRight($module,$right){return $module==='chinaplanetcustomercenter'&&in_array($right,$this->rights,true);}
}
$actor=new M121ScopeActor();$base='/custom/chinaplanetcustomercenter/funding.php';
foreach(array(array(),array('read'),array('write')) as $rights){$actor->rights=$rights;$url=CustomerAccountView::fundingUrl($actor,7,$base,'en_US');m121s_assert(($url!=='')===!empty($rights),'Only existing CC rights enable owner link');if($url!==''){parse_str(parse_url($url,PHP_URL_QUERY),$q);m121s_assert($q['socid']==='7'&&!isset($q['project'])&&!isset($q['task']),'Link is fixed customer pool, not project/task cash');}}
$actor->rights=array();$actor->admin=1;m121s_assert(CustomerAccountView::fundingUrl($actor,7,$base,'en_US')!=='','Admin link');
foreach(array('socid','fk_soc') as $key){$actor->$key=7;m121s_assert(CustomerAccountView::fundingUrl($actor,7,$base,'en_US')==='','External actor cannot acquire internal owner link');$actor->$key=0;}
$actor->statut=0;m121s_assert(CustomerAccountView::fundingUrl($actor,7,$base,'en_US')==='','Inactive denied');$actor->statut=1;$actor->id=0;m121s_assert(CustomerAccountView::fundingUrl($actor,7,$base,'en_US')==='','Anonymous denied');$actor->id=7;
$root=dirname(__DIR__,2);$statement=array('customer'=>array('rowid'=>7,'nom'=>'Synthetic customer'),'balance_minor'=>'10000','rows'=>array());
foreach(array('en_US','ar_SA') as $lang){$labels=array();foreach(file($root.'/custom/chinaplanetoperations/langs/'.$lang.'/chinaplanetoperations.lang',FILE_IGNORE_NEW_LINES) as $line){if(strpos($line,'=')!==false){list($k,$v)=explode('=',$line,2);$labels[$k]=$v;}}$config=array('lang'=>$lang==='ar_SA'?'ar':'en','print'=>false,'customer'=>7,'project'=>11,'scope_labels'=>array('title'=>$labels['AccountManualScopeTitle'],'note'=>$labels['AccountManualScopeNote'],'link'=>$labels['AccountCustomerFundsLink']),'funding_url'=>CustomerAccountView::fundingUrl($actor,7,$base,$lang));$html=CustomerAccountView::fragment($statement,$config);$dom=new DOMDocument();libxml_use_internal_errors(true);$dom->loadHTML('<?xml encoding="utf-8" ?>'.$html,LIBXML_NONET);libxml_clear_errors();$x=new DOMXPath($dom);m121s_assert($x->query('//*[@id="cpo-account-scope"]')->length===1,'Scope notice renders');m121s_assert($x->query('//*[@id="cpo-account"]//*[@id="cpo-account-scope"]')->length===0,'Notice survives manual JS root rerenders');m121s_assert(strpos($dom->textContent,$labels['AccountManualScopeTitle'])!==false,'Native scope label');m121s_assert($x->query('//*[@id="cpo-account-scope"]//a')->length===1,'Authorized fixed owner link');$raw=$x->query('//script[@id="account-config"]')->item(0)->textContent;$boot=json_decode($raw,true);m121s_assert($boot['statement']===$statement,'No new money fields/native data adapter');$config['project']=22;m121s_assert(strpos(CustomerAccountView::fragment($statement,$config),'socid=7&amp;lang='.$lang)!==false,'Display/project filters never retarget customer funds');$config['print']=true;m121s_assert(strpos(CustomerAccountView::fragment($statement,$config),'href="'.$base)===false,'Print scope does not add navigation');$config['print']=false;$config['funding_url']='javascript:alert(1)';m121s_assert(strpos(CustomerAccountView::fragment($statement,$config),'href="javascript:')===false,'Invalid URL scheme rejected');$config['scope_labels']['title'].='<img src=x onerror=alert(1)>';$h=CustomerAccountView::fragment($statement,$config);m121s_assert(strpos($h,'<img')===false&&strpos($h,'&lt;img')!==false,'Labels escaped');}
$page=file_get_contents($root.'/custom/chinaplanetoperations/tasks/account.php');
m121s_assert(strpos($page,"CustomerAccountView::fundingUrl(")!==false&&strpos($page,"\$statement['customer']['rowid']")!==false,'Link starts from validated statement customer');
